import{_ as t,o as i,c as n,ah as r}from"./chunks/framework.Bja9t6Wf.js";const m=JSON.parse('{"title":"Projekt-Update: Das Horten-Mysterium","description":"","frontmatter":{},"headers":[],"relativePath":"logbuch/horten-projekt.md","filePath":"logbuch/horten-projekt.md"}'),a={name:"logbuch/horten-projekt.md"};function s(o,e,u,l,h,c){return i(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="projekt-update-das-horten-mysterium" tabindex="-1">Projekt-Update: Das Horten-Mysterium <a class="header-anchor" href="#projekt-update-das-horten-mysterium" aria-label="Permalink to &quot;Projekt-Update: Das Horten-Mysterium&quot;">​</a></h1><p>Heute haben wir einen großen Schritt in der Stoffentwicklung gemacht. Das Thema unserer Mockumentary steht fest: <strong>&quot;Das Horten-Mysterium: Eine fabelhafte Fiktion von Macht, Geld und Perlen&quot;</strong>.</p><h2 id="die-vision" tabindex="-1">Die Vision <a class="header-anchor" href="#die-vision" aria-label="Permalink to &quot;Die Vision&quot;">​</a></h2><p>Wir beleuchten die schillernde und zugleich düstere Biografie von Heidi Goëss-Horten und den geschäftlichen Aufstieg von Helmut Horten. Dabei bewegen wir uns auf dem schmalen Grat zwischen historischer Anlehnung und satirischer Überzeichnung.</p><h2 id="traumbesetzung" tabindex="-1">Traumbesetzung <a class="header-anchor" href="#traumbesetzung" aria-label="Permalink to &quot;Traumbesetzung&quot;">​</a></h2><p>Für die Schlüsselszene der &#39;Marktbereinigung&#39; (Teil 2) haben wir eine absolute Traumbesetzung im Kopf:</p><ul><li><strong>August Diehl</strong> als Helmut Horten (mit dieser kühlen, präzisen Intensität).</li><li><strong>Oliver Masucci</strong> als Bankier Schreck (laut, hessisch, gierig).</li></ul><h2 id="szenen-einblick" tabindex="-1">Szenen-Einblick <a class="header-anchor" href="#szenen-einblick" aria-label="Permalink to &quot;Szenen-Einblick&quot;">​</a></h2><p>In einer ersten Dialog-Skizze trifft Hortens rheinische Kälte auf Schrecks hessische Hemmungslosigkeit. Es geht um &#39;Marktbereinigung&#39; – ein Begriff, der in diesem Kontext eine schaurige Doppeldeutigkeit bekommt.</p><blockquote><p><em>&quot;Es geht nicht darum, was sie bekommen. Das ist sentimental. Es geht um die Zukunft des deutschen Einzelhandels.&quot;</em> – fiktiver Helmut Horten</p></blockquote><p>Die Arbeit am Drehbuch geht weiter. Bleibt dran!</p><hr><ul><li><a href="./index.html">Zurück zum Logbuch-Index</a></li><li><a href="./interview-zitzewitz.html">Exklusiv-Interview mit Dr. von Zitzewitz</a></li></ul>',13)])])}const g=t(a,[["render",s]]);export{m as __pageData,g as default};
